import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"誠齋易傳卷十四","description":"誠齋易傳 - 誠齋易傳卷十四","frontmatter":{"title":"誠齋易傳卷十四","description":"誠齋易傳 - 誠齋易傳卷十四"},"headers":[],"relativePath":"classics/chengzhai/015.md","filePath":"classics/chengzhai/015.md"}'),c={name:"classics/chengzhai/015.md"};function r(i,p,n,_,o,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="誠齋易傳卷十四" tabindex="-1">誠齋易傳卷十四 <a class="header-anchor" href="#誠齋易傳卷十四" aria-label="Permalink to “誠齋易傳卷十四”">​</a></h1><p>欽定四庫全書</p><p>宋楊萬里撰䷲ 震下震上</p><p>震：亨。震來虩虩，笑言啞啞。震驚百里，不喪匕鬯。彖曰：「震」，亨。「震來虩虩」，恐致福也。「笑言啞啞」，後有則也。「震驚百里」，驚遠而懼邇也。出可以守宗廟社稷，以為祭主也。震所以「亨」者，何也？動而懼則亨也。懼非惶擾失守之謂也，懼而敬也。惟懼故敬，惟敬故無懼。無懼者，非不懼也，懼始乎來，終乎散也。當天下之大事震動而來也，吾虩虩然必為之恐懼而顧慮焉，必求其所以應之，使大事為無事焉，斯可以轉禍為福，移懼為喜，而笑言啞啞矣。故震雷能驚百里，而不能失匕鬯於主祭之才；羑里能難文王，而不能傷文明於柔順之聖。蓋執匕鬯以祭者，一敬之外無餘念，一鬯之外無餘知。當是之時，白刃前臨，猛虎後迫，皆莫之覺，故震雷驚百里亦莫之聞，敬有所甚，懼有所忘也。能如是，天下可懼之大事，孰能驚之者？其出而主宗廟社稷，優為之矣。高祖當項籍，光武遇尋、邑是已。震為長子，故言主祭。又震為雷，為動，曰「出」者，猶曰明天子出矣。說卦曰：「帝出乎震。」劉備聞迅雷失匕箸，託也。舜之烈風雷雨弗迷，震之祭主，不喪匕鬯，敬也。出字上脫「不喪匕鬯」四字。</p><p>象曰：瀳雷，震，君子以恐懼修省。震者，雷也。一雷已威矣，況瀳而重乎？天之雷以驚夫不敬者也，不敬者猶驚，而況敬君乎？君子敬者也，一雷已驚矣，而況瀳雷乎？然君子非徒驚也，有功用焉。聞雷而恐懼，驚也，驚而已矣，過則舍之，徒驚也。君子則不然，恐懼以先之，修省以繼之。修省者，恐懼之功用也。修其身，省其過，則恐無恐，懼無懼矣。</p><p>初九，震來虩虩，後笑言啞啞，吉。象曰：「震來虩虩」，恐致福也；「笑言啞啞」，後有則也。彖辭已言之矣。爻、彖二辭同，或者其一重出。「後有則」者，喜而不失節也。</p><p>六二：震來厲，億喪貝，躋於九陵，勿逐，七日得。象曰：「震來厲」，乘剛也。</p><p>時有險易，則勢有詘伸。故天下無常險，亦無常詘。險過則易，詘甚則伸。以六二之柔，乘初九之剛，險也；以六二之靜，應初九之動，詘也。方「震」之始初，遇九之猛厲，勃然而動，駭然而來，何可當也？六二才與位俱柔，若不勝其憤，起而逐之，奚而不喪？惟能以柔避剛，以靜馴動，遠避而勿逐，俟之久而剛自衰，則吾無喪而有得矣。險者易，詘者伸，非有得乎？高祖避項而入漢中，光武避更始而出河北，得「震」六二之義矣。厲，猛也；「躋於九陵」，避之遠也。億，度也；貝，其所有之資也，度其逐之，則喪其所有也。「七日」，久也。</p><p>六三：震蘇蘇，震行，無眚。象曰：「震蘇蘇」，位不當也。</p><p>不患無位，有位患也；非患位也，才儉於位之患也。六三以柔懦之才，逢震擾之世，居下卦之上，非位之不當乎？君子所以為六三懼也。「蘇蘇」，懼之至也。然則奈何？曰：行而去之可也。辭難避事，臣子之義乎？曰：是臣子之義也。不才雲才，隕身細也。隕國細乎？吾才不稱吾位，吾去之，天下獨無才稱其位者乎？鮑叔遜夷吾，子皮遜子產，去無才得有才，豈惟無災眚乎？國之福，身之福也。薳子馮不為令尹，蔡謨不拜司徒，可以無青矣，抑可以為次矣。九四：震遂泥。象曰：「震遂泥」，未光也。</p><p>九四以一陽之孤，陷四陰之內，處至陰之位，百鍊化為繞指，一齊咻於眾楚矣。以此居震擾之世，安能致遠而不泥，光大而有濟乎？劉向、恭、顯雜處漢朝，珣、瑜、伾、文並居唐位是已。</p><p>六五：震往來，厲。億無喪，有事。象曰：「震往來厲」，危行也。其事在中，大無喪也。</p><p>六五，震之君也。當震動之世，為正位之君，宜其憤起奮發，撥亂反正，以大有為於天下也。今戒之曰：毋進而往，往則為上六之震極，是往亦危也；毋退而來，來則乘九四之至剛，是來亦危也。必也深思焉，長慮焉，億之於心，度其得中而無喪其所有焉，斯足矣。然則天下紛紛，何時定乎？曰：治人者必自治，料敵者必料己。五固震之君也，六則陰柔而無陽剛之才者也。當動之時，無動之才，與其動而喪吾之所有，不若靜而不喪吾之所有。其周平王、晉元帝之事乎？上六：震索索，視矍矍，徵兇。震不於其躬，於其鄰，無咎。婚媾有言。象曰：「震索索」，中未得也。雖兇無咎，畏鄰戒也。立弱子於千仞之上，而觀人與虎鬥於其下，其氣豈不索然而盡？其視豈不矍然而愕乎？「震」之上六似之。六以柔怯之資，居震懼之極，下臨五爻之動，其索然矍然宜也。然聖人一則以驚，一則以安。曰「徵兇」，言往則兇，驚之之辭也；曰「無咎」，言不往則無咎，安之之辭也。奚而往則兇？往則犯九四之剛，奚而不往則無咎？我躬遠於剛，而我之鄰六三實當之也。然聖人雖安之，而終再以三警之，曰：汝雖無咎，而鄰之「蘇蘇」，亦不可不畏不戒也。天下之禍，莫大乎於其鄰，而於其身次焉，何也？身者必防，鄰者必玩也。虞受晉寶以滅虢，不知乃所以自滅。楚聽秦賂以伐齊，不知乃所以自伐，玩故也。江亡而秦穆懼，吳亡而晉國吊，其知所謂雖無咎而畏鄰戒者與？「震」之六爻，一言以蔽之，曰：「君子以恐懼修省，婚媾有言」，亦謂鄰也。「中未得」，謂懼而不自得也。三與上應曰「鄰」，說者以五為鄰，五，君也，非鄰也。䷳ 艮下艮上</p><p>「艮」其背，不獲其身，行其庭，不見其人，無咎。</p><p>「艮」，山也。不動如山，止之至也。曰「艮其背」，何也？易者，象也。象者，狀物以明理也。故「頤」如人之頤，噬嗑如人之噬，背如二人相重背而立也。二陰虛而眾者，耳目手足也。一陽實而孤者，背也。「艮」之貞，面內而背外，是「艮其背」，不自復見其身也。其悔亦面前人之背，而不見後人之面，是行其庭而不見其人也。君子觀貞之象，於是得忘我之學；觀悔之象，於是得忘物之學。忘我則中不出，忘物則外不入。中不出，外不入，止之至也。毋意，毋必，毋固，毋我，勿視勿聽，勿言，勿動，「艮其背，不獲其身」也。堂高數仞，食前方丈，侍妾數百，得志而弗為，行其庭，不見其人也，又何咎？貞內，故「艮其背」；悔外，故「行其庭」也。「艮其背」之上，疑脫一「艮」字。彖曰：「艮」，止也。時止則止，時行則行，動靜不失其時，其道光明。「艮其止」，止其所也。上下敵應，不相與也，是以「不獲其身，行其庭，不見其人，無咎」也。</p><p>「艮，止也」，非止而不行之為止也。「時止則止」，止也。「時行則行」，亦止也，非行之為止也。時乎當行，道乎可行，吾斯行焉，吾雖行，然止乎道也。時乎當止，道乎可止，吾斯止焉，非吾止，亦止乎道也。行止聽乎己，耦而耕，逾而避，君子不以為止；行止聽乎道，聘列國，見齊梁，君子不以為不止。何也？彼之止，非止乎道也；此之行，亦止乎道也。如北辰焉，杓建無定指，而北辰有定居，故曰：「動靜不失其時，其道光明。」「艮其止，止其所也」，而孔子亦曰「北辰居其所」。君子之止其所，即北辰之居其所也。「上下敵應，不相與」者，前一人面內而不自見其背，況見己之面乎？後一人見前人之背，而不見前人之面，況見後人之面乎？所以釋</p><p>「艮其背，不獲其身；行其庭，不見其人」之卦辭也。象曰：兼山，「艮」，君子以思不出其位。</p><p>「艮」，山也。山，不動之物也。一山已不動，況二山相重乎？山兼重而二焉，止而不動之至也。君子體之，以思不出其位，可得而動乎？縕袍，縕袍立狐貉。狐貉立，止其位也。典禮以禮聞，典樂以樂聞，亦止其位也。前二者出位而思，不惟不得狐貉，並縕袍而喪之矣；後二者出位而思，不惟不得音樂，並禮文而喪之矣。大哉止乎！有止而絕之者，有止而居之者，有止而約之者。「艮其背」，所以絕人慾而全天理，此止而絕之也；時止時行，必止乎道，此止而居之也；思不出其位，而各止其分，此止而約之也。大哉止乎！夫止，一端而已乎！</p><p>初六：艮其趾，無咎，利永貞。象曰：「艮其趾」，未失正也。止不善必在初，止之於初，猶不能止之於末，而況肆之於初者乎？顏子之不遠復，止一己之不善於初者也。漢文即位之初，喜嗇夫之辯捷，而張釋之極言其害，止其君之不善於初者也。顏為幾乎聖，而文為七制之主，止於初之效也。「艮」，止也。初六，止之初也，居腓之下，偶而散，趾之象也。以六之柔而靜，此趾之止而不行者也。聖人猶有憂焉，曰汝能止其初，猶宜止其終。曰「利永貞」者，止其終之謂也。然六止而初動，故但言未失正。</p><p>六二：艮其腓，不拯其隨，其心不快。象曰：「不拯其隨」，未退聽也。</p><p>六二，一卦之大臣也。大臣者，以道事君，不可則止。今則不然，居大臣之位，逢其上之剛，必有順柔之忠而後可。譬之一身，以己下九三，則猶腓也；九三在上，則猶背也。九三陽也，六二陰也。陽倡則陰必和，背動則腓必隨。以六二之柔而欲止九三之剛，以六二之腓而欲止九三之背，其能與否，已昭昭矣。然必觀其心，而後君子小人可判也。古之人於其上之不善，有拯而不隨者，有先隨而後拯者，有先拯而後隨者，有不拯而隨者，有不拯而隨其心不然者。龍逢、比干，拯而不隨也。楚靈王之問子革，先隨而後拯也。伍被之答淮南，先拯而後隨也。蜚廉、惡來，不拯而隨也。君曰「好色」，亦曰太王好色；君曰「好貨」，亦曰公劉好貨，不拯而隨，而心不然也。六二：「艮其腓」，非不欲止其背之動也，而柔不勝剛，下不勝上，故曰「不拯其隨」。非樂隨也，外不得不隨，而中不得已也，故曰「其心不快」，言其不得已而隨也。又曰「未退聽也」，言其雖不得已而隨，亦未肯退聽其上之輕動也。九三非君也，而居六二之上也，六二不得不隨也。君子於「艮」之六二，察其跡而哀其心。六二居背之下，偶而立，腓之象。「腓」，脛肉也。六二中正，故不快，故未退聽。</p><p>九三：艮其限，列其夤，厲薰心。象曰：「艮其限」，危薰心也。君子之學，至於止其所而如山之不動，可以免矣。故初與四皆「無咎」，五「悔亡，上吉」，二惟小不快而已。今九三曰「厲」，曰「危」，曰「薰心」，何也？蓋三居物我之交，內外之際，而九三以陽處陽，剛而進，躁而動者也。人有夜行而遇子都者，己先焉，子都後焉，不惟子都不己見，己亦不子都見也。旦而一揖焉，則喜子都之美矣。喜生於見，見生於不相背也。九三下卦之背，所以背六四而面內者也。惟剛而進，躁而動，則有時回面而外向矣。此內欲之所由出，而外邪之所從入也。故聖人戒之曰：爾幸能「艮其背」矣，今而「列其夤」之脊，自危其心，使之有定列而不亂行也。爾幸能「行其庭」，不見其人矣，今宜「艮其閾」之限，自危其心，使之不逾閒而不出戶庭也。昔也行其庭，今也不逾閾，則並與庭而不行。昔也「艮其背」，今也「列其夤」，則並與背而不動。何九三之能然也？亦九三剛而進之力也。惟其剛，故反躁而靜，如百鍊之金而不可革；惟其進，故反動而止，如介然之石而不可轉。九三之剛者，質之美也。</p><p>九三之「艮其限，列其夤，厲薰心」者，學之功也。然則學顧可少哉？故益不以舜之聖而忘逸樂之戒，周公不以成之賢而廢遊田之規。大哉學乎！「夤」亦背也，「厲」亦危也。「危薰心」者，操心至危，若有薰蒸其心者。九三奇而橫，有門限之象。「艮」為門闕。</p><p>六四：艮其身，無咎。象曰：「艮其身」，止諸躬也。</p><p>六四居大臣之任，上欲止其君之不善，下欲止天下之不善，惟不止諸人，不咎諸人，而自止諸躬，則得之矣。楚莊王好獵，而樊姬不食禽獸之肉；太宗喜武功，而魏徵不視七德之舞。此其事也。王吉之賢，能疏昌邑之獵；楊綰之清，能減汾陽之樂。此其效也。四居體之半，身之象也。</p><p>六五：艮其輔，言有序，悔亡。象曰：「艮其輔」，以中正也。六五，「艮」之君也，其言如絲之至微，其出如紼之至大。成王一言而天返風，景公一言而妖星退，可不謹哉！與其言而未善，寧止其輔頰而不言。止而不止，非不言也，審而後言也。審而後言者，是惟不言，言必有序矣，何悔之有？故高宗三年不言，一言而四海鹹仰。威王三年不鳴，一鳴而齊國震驚。「艮」之六五所以能「艮其輔」者，以其德之中正而已。所謂「有德者必有言」也。五居上而偶有口，胠而不合之象，故為輔頰。</p><p>上九：敦艮，吉。象曰：「敦艮」之吉，以厚終也。</p><p>上九以德之剛居止之終，其高風勁節，剛健篤實，如泰山喬嶽之巔，其止豈可搖，其厚豈可移哉？此伊尹將告歸，仲尼不逾矩之事乎？敦，厚也。上九亦背之象，故「厚」。䷴ 艮下巽上 漸女歸吉，利貞。彖曰：漸之進也，「女歸吉」也。進得位，往有功也。進以正，可以正邦也。其位，剛得中也。止而巽，動不窮也。</p><p>臣從君，如女從夫。女之從夫，聘則漸，奔則速。漸則正，速則邪。正則妻，邪則妾。臣之從君，可速而不漸，邪而不正哉？漸而進，則獲乎上而有功。「正而進」，則正其身以及國。「漸而進」者，誰也？初六、六二、九三、六四、上九也。「獲乎上」者，孰為上也？九五也。九五以剛中之盛德，居天下之大位，故曰「其位」，指而言之也。諸爻得乎有位之大君，故曰「得位」，以此得彼也。艮止巽順，止則靜，順則謙。既靜且謙，其進豈不正而漸哉？有不動，動斯達，何窮之有？長女歸少男，故曰「女歸」。</p><p>象曰：山上有木，漸。君子以居賢德善俗。</p><p>木在山，木因山而高也。山有木，木非人所植而固有也。非人所植，則聽於天而無所用其力；因山而高，則浸以長而不驟至於高，所以為漸也。君子體之，以此處己，則不自賢其德，而居於賢德者之間，故賢德者推而高焉；以此處人，則不速責其善，而俟其人之自善，故風俗化而善焉。又豈獨進得位、進以正一端而已哉？或以女，或以木，或以鴻，其象亦非一端而已。「巽」為長女，又為高，鴻象也。</p><p>初六：鴻漸於幹，小子厲，有言，無咎。象曰：「小子」之「厲」，義無咎也。</p><p>「鴻」，雲飛水宿之物也。當其水宿而進，于飛必有漸也，故始進則漸升於水涯之江干。如初六之君子在下而始進，亦或自抱關擊柝而升，或自乘田委吏而升也。匹夫孺子如燕雀焉，安知鴻之志哉？或欲厲而危之，或有言以毀之，安知君子之不卑小官，少安無躁之節哉？為君子者，付之莞爾，勿深咎焉可也。非不咎也，其義不足咎也。如足咎，則孔子慍武叔，孟子怨臧倉矣。「艮」，初山之麓，故為「幹」。又偶立，有江干兩岸之象。</p><p>六二：鴻漸於磐，飲食衎衎，吉。象曰：「飲食衎衎」，不素飽也。鴻自幹而漸進於磐石之上，則高而安矣。此六二漸進而居大臣之位之象也。然居大臣之位，食吾君之祿，豈曰「素餐」乎？亦欲置國家於磐石之安，納君民於衎衎之樂而已。故傅說之志在中興商高，而「非後」，則不食其祿；孟子之志在平治天下，而「食方丈」則得志不為「艮」。二山之石，故為「磐」。「艮」為小石。</p><p>九三：鴻漸於陸，夫徵不復，婦孕不育，兇。利禦寇。象曰：「夫徵不復」，離群醜也。「婦孕不育」，失其道也。「利用禦寇」，順相保也。</p><p>止極者，進必銳；伏久者，飛必高。九三居於「艮」之終，止之極也；壓於「巽」之下，伏之久也。以陽居陽，進必銳，飛必高也。是故自幹自「磐」，一飛而登於高平之陸，知進而已耳，好高而已耳。知進而已，故其類雖眾，豈復回而顧？好高而已，故非類在上，亦必合而從初六、六四、九三之群類也。九三知進，則往而不反，決焉棄其群類而離絕之矣。六四非九三之耦也，九三好高則比而相悅，靦焉孕而不育，亦不知媿恥矣。聖人戒之曰：汝胡不正汝心，明汝目而察之乎？初六、六二，汝之類也；六四，汝之寇也。汝盍亦和順於汝之類，而相與扞禦於汝之寇乎？如是，則汝與初六、六二可以相保，而免為六四之所兇災矣。豈惟無兇，又且利焉，故曰「利禦寇」。故酈寄舍祿、產而從平、勃，「利禦寇」也；蕭至忠舍明皇而從太平公主，「婦孕不育，兇」也。「醜」，類也。「夫」，九三也；「婦」，六四也。「艮」三，山之平，故為「陸」。六四：鴻漸於木，或得其桷，無咎。象曰：「或得其桷」，順以巽也。</p><p>六四漸進而登於木，則又在陸之上矣。以九三之剛而漸於陸，今六四乃超九三而出其上，此危道也。惟降而棲於可椽可桷之卑枝，則庶幾「無咎」與！「漸於木」者，飛而至也；「得其桷」者，「順以巽」也。君子之漸進於高位，不幸而在剛暴小人之上，非「順而巽」，「巽」而降，未有能免者。故子文下子玉而安陽，處父上趙盾而見殺。三御四陰，寇陽也；四順三柔，巽剛也。四出「艮」之上，為木、為風，故乘風而升於木。</p><p>九五：鴻漸於陵，婦三歲不孕，終莫之勝，吉。象曰：「終莫之勝，吉」，得所願也。</p><p>九五以剛明中正之君，居崇高富貴之位，此鴻之進於丘陵最高之地之象也。下有六二柔順中正之大臣，九五與之合志一德，以大有為於天下，此如鴻之遇順風，橫四海也，何難之有？然猶三歲而不合，不合而無成者，何也？五欲親二，而九三在旁以間之，如蒯通之說韓信；二欲親五，而六四近上以間之，如管、蔡之毀周公。此其所以「婦三歲不孕」也。惟君臣皆有中正之德，故九三間臣之計不行於六二，六四間君之計不行於九五，終不為其間之所勝，而底於「吉」也。彼不能勝此，則此之志願得矣；君之志願得，則豈惟位之高如丘陵哉？功業之高亦如丘陵矣。雖然，豈一日之致哉？亦三歲之漸而至也。「漸於陵」，非進於位之漸也，進於功業之漸也。故文皇之治，不見於貞觀之初，而見於三年之後。開元、元和亦然。君臣遇合之艱也，成就之不易也如此。而或者欲一言而悟，期年而化，或者不妄則易，妄矣。「婦」謂六二，「不孕」謂功無成。五出山木之上，故為「陵」。「鴻漸」而至於「陵」，乘「巽」之風故也。又「巽」為高。</p><p>上九：鴻漸於陸，其羽可用為儀，吉。象曰：「其羽可用為儀，吉」，不可亂也。九三：漸於陸，上九復漸於陸。何也？「漸」之進，至於九五之「漸於陵」，高之極也，不可逾矣。逾則僭，故九三下卦之極，上九上卦之極，其進也皆至於高平之陸而止矣。然九三之「漸於陸」，躁於進也，雖平而高；上九之「漸於陸」，安於進也，雖高而平。何也？自「幹」、自「磐」而至於「陸」，則其高為驟；自「陸」、自「木」、自「陵」而復至於「陸」，則其進為退。上九以剛陽之德，秉謙巽之極，名居一卦之上，實出一卦之外，其位彌高，其心彌下，其進彌徐，其退彌速。此其羽翼翔集，截然而不可亂，豈不足以高出一世而為天下之儀表乎？故良平、安劉之策，不妙於四老人；寇、鄧重漢之功，不宏於一客星。然則學者欲學「漸」之一卦，將學其進乎？將學其不進乎？巽為進退，又「巽」為風，至上九，風之衰也。衝風之衰，不能起毛羽，故鴻復反於陸。艮、巽皆上實而下散，鴻舒翼之象。䷵ 兌下震上</p><p>歸妹，徵兇，無攸利。彖曰：「歸妹」，天地之大義也。天地不交而萬物不興。「歸妹」，人之終始也。說以動，所「歸妹」也。「徵兇」，位不當也。「無攸利」，柔乘剛也。</p><p>「歸妹」者，嫁女之家，非娶婦之家也。何以知其為嫁女之家？漸曰「女歸」，自彼歸我之辭，此娶婦之家也。今曰「歸妹」，自我歸彼之辭，婦人謂嫁曰「歸」，此嫁女之家也。曷為不曰「歸女」而曰「歸妹」？女者，愛之鐘也。「妹」者，孤之窮也。何以知「妹」者孤之窮也？「妹」之為言，幼小之辭也，無父而有兄之辭也。豈有父在而女稱妹哉？「妹」者，敵兄之辭也。無父而歸於人，孰歸之也？兄歸之也。孰為之兄？震是也。故兌者少女，震之妹也。震者長男，兌之兄也。曷為歸妹？「徵兇，無攸利」也？不待兄以己歸於人，而自往焉，是淫奔也。淫惡之大，奔，行之醜。聘則妻，奔則妾，非兇乎？又何利之有？舜之從堯，四嶽歸之堯也。孔明從先主，徐庶歸之先主也。伯姬之歸宋，魯成公歸之宋也。此夫婦君臣之大義也。非夫婦君臣之大義也，天地之大義也。天地不交萬物熄，男女不交萬物熄，君臣不交萬物熄。故曰：「歸妹，人之終始也。」嫁者，女之終；娶者，男之始也。說以動者，兌說而震動也。伯兄三夜不息燭，不亦動乎？少妹之孤身有所依歸，不亦說乎？惟不待兄之命而自徵行以往焉，則兇，則無攸利爾，而況位不當，柔乘剛乎？王輔嗣以為少女與長男交，是誤以嫁為娶也。上下卦言歸妹者四，初無取女之辭如鹹，亦無女歸之辭如漸，何從而知其交？又以妹從姊而為媵，愈失之矣。巽為姊，經有兄而無姊，然則震之嫁其妹，將焉歸？少女歸於少男，鹹是已。「柔乘剛」，謂三陰皆乘三陽，陰位乎陽之上，故位不當。</p><p>象曰：澤上有雷，「歸妹」。君子以永終知敝。</p><p>雷興雨則澤益滋，兄舉禮則妹有歸，此「歸妹」之象也。傳曰：「昏姻者，禍福之始。」故姜任興周，文、哀禍魯，叔姬辱身；董祁訴夫，夏姬滅國。君子於「歸妹」之始，必慮永久之所，終必知其歸之所敝也。豈惟昏姻？忠敝必野，文敝必僿，一代之敝也；革俗必弱，從俗必強，一國之敝也；清必隘，和必不恭，一行之敝也；兼愛必無父，為我必無君，一學之敝也。豈惟昏姻！</p><p>初九：歸妹以娣，跛能履，徵吉。象曰：「歸妹以娣」，以恆也；「跛能履，吉」，相承也。</p><p>初九之「跛能履」，能履則非跛也；九二之「眇能視」，能視則非眇也。非跛言跛，非眇言「眇」，眇言「昧」，跛言「弱」也。幼孤之妹，昧弱不振，待兄以振者也。初九在下，非妹也，妹之娣媵也。故驪姬之娣生卓子，戴己之娣生惠叔，皆媵也，非匹也。然卦辭言「歸妹徵兇」，而初九為娣則「徵吉」，何也？「徵兇」者，不待兄之命而自往；「徵吉」者，待女君之命而已往也。凡師能左右之曰「以」，今曰「歸妹以娣」，是娣聽女君左右之也。初九以妹媵之，卑剛貞之德，而能體昧弱之柔，承女君之尊，所以吉而相承也。「恆」者，能安其分之當卑也。「歸妹以娣」，其猶「泰茅」之「茹」乎？非娣之賢也。故君子不賢管仲、子產，而賢鮑叔、子皮。</p><p>九二：眇能視，利幽人之貞。象曰：「利幽人之貞」，未變常也。初九、六三、九四、六五皆言「歸妹」，而九二獨不言，何也？九二之位，下卦之尊者也，即妹之身也。妹之身而言「利幽人之貞」，所謂幽人者誰？幽人者，男女賢德之通稱。「履」之九二曰「幽人貞吉」，言君子之幽貞也；「歸妹」之九二曰「利幽人之吉」，言少妹之幽貞也。九二以孤幼昧弱之身而有視遠之聰明，以女子無父之訓而有幽閒中貞之賢德，體陰而陽其性，質柔而剛其德故也。幽則至靜而不可動，貞則至堅而不可渝，皆剛陽中正之常德而不變者也，故曰「未變常」也。九二：其女夷齊乎？其宋伯姬、陳孝婦之儔乎？</p><p>六三：歸妹以須，反歸以娣。象曰：「歸妹以須」，未當也。九二言幽貞未變之德，而不言其所歸，此未嫁而待禮也，故曰「歸妹以須」。「須」者，待也。然方九二未嫁以待禮，而六三欲躐出於九二之上，此已挾綠衣上僭之心矣。故聖人從而正其分，曰：汝曷不反而歸於娣媵之列乎？又曰「未當」者，深貶其僭之不當也。其在外則皇父卿士番為司徒之時乎？</p><p>九四：歸妹愆期，遲歸有時。象曰：「愆期」之志，有待而行也。九四亦少妹之兄也，而「歸妹」愆期而不嫁，有待而後行，何也？待嫡兄之命也。夫九二以少妹之孤，視聽聰明，斯已賢矣；剛陽得中，此又賢也；幽貞不變，此又賢也；歸而須禮，此又賢也；嫁而愆期，此又賢也。其三聘之尹、三顧之葛也與？</p><p>六五：帝乙歸妹，其君之袂，不如其娣之袂良，月幾望，吉。象曰：「帝乙歸妹，不如其娣之袂良」也。其位在中，以貴行也。</p><p>九二之少妹，在二則幽貞而不變，至三則須禮而不輕，至四則愆期而未行，然則何時而歸於人乎？待六五之命而後行也。六五以帝乙之賢，居至尊之位，體中正謙柔之德，而九二之賢女為之妹，以是兄歸是妹，豈不光華焜燿於而國而家哉？於此而下嫁於諸侯，又能自謂我雖女君也，娣雖吾妾也，不以己為過之，而自以為不如，位高而志益卑，身貴而行愈謙，此帝妹之所以愈賢與！推而放諸君道，高帝不如三傑，文帝不及賈生，其庶幾乎！彼謂五帝，其臣不及其聖，豈惟五帝之罪人，亦歸妹之罪人也。月與日望則相敵，幾望者，月遜日也，婦遜夫之象也，故「吉」。觀帝妹之遜其夫，知帝乙之訓其妹；觀帝乙之訓於妹，知帝乙之孝於親。蓋吾親有遺愛，吾能解其憂；吾親有所託，吾能副其託，不曰孝乎？故帝妹之遜，可能也；帝乙之訓，難能也；帝乙之訓，可能也，帝乙之孝，難能也。大哉，帝妹之遜乎！大哉，帝乙之孝乎！至於武王集文王未集之統，成王終武王未終之功，抑又歸妹之大者與！袂，袖也。假衣以明其人，而不斥其人也。</p><p>上六：女承筐，無實；士刲羊，無血。無攸利。象曰：上六「無實」，承虛筐也。六，陰也，故虛；虛則無德。居上，尊也，尊則為兄。尊而無德，其少妹不令之兄與？故九二之為女，奉承之於下，如奉虛筐而無幣帛以實其筐；上六之為士，刲羊告廟於上，如執虛器而無血膋以實其器。少妹疇依焉？儻無六五以主少妹之昏禮，前人目不瞑矣，一妹不足託宗廟社稷乎？易者象也，上卦☳有虛筐之象，「兌」為羊，上六而在外朝，為許靖，為王衍。誠齋易傳卷十四。</p>',52)])])}const m=a(c,[["render",r]]);export{h as __pageData,m as default};
